from flask import Flask, jsonify, request
from functools import wraps
app = Flask(__name__)
def auth_required(fn):
    @wraps(fn)
    def w(*a, **k):
        if request.headers.get("Authorization", "") != "Bearer t":
            return jsonify(error="unauthorized"), 401
        return fn(*a, **k)
    return w

